('city_denton', 'Denton', 'TX', 'denton', 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);

UPDATE "Club" SET "status" = 'ACTIVE', "lastVerifiedAt" = '2026-11-11', "description" = 'Its own site says: "We play by National Mah Jongg League rules and keep score throughout the session." Mahj 101 and Guided Play classes ("We''ll introduce you to the tiles, the National Mah Jongg League card, and the flow of the game") at a studio in Stony Point Fashion Park, South Richmond; club sessions are 8-week blocks or a monthly membership, and class dates are booked through the group''s scheduler.', "website" = 'https://www.letsmahjrva.com/', "sourceUrl" = 'https://www.letsmahjrva.com/' WHERE "slug" = 'richmond-let-s-mahj-rva' AND "status" = 'NEEDS_REVIEW';
UPDATE "Club" SET "status" = 'ACTIVE', "lastVerifiedAt" = '2026-11-11', "description" = 'The La Jolla Community Center''s class page says: "This class will teach you the more advanced strategies of playing American Mahjong according to the NMJL Rules and Guidelines." and "This beginner-friendly evening course will teach you the fundamentals of the game, including tile recognition, the National Mah Jongg League card, game setup, strategy, and scoring." Six-week beginner courses and evening beginner and intermediate classes; the current beginner course is sold out.', "website" = 'https://www.ljcommunitycenter.org/', "sourceUrl" = 'https://www.ljcommunitycenter.org/' WHERE "slug" = 'san-diego-la-jolla-community-center-american-mahjong' AND "status" = 'NEEDS_REVIEW';
UPDATE "Instructor" SET "status" = 'ACTIVE', "lastVerifiedAt" = '2026-11-11', "notes" = 'Boutique mahjong studio inside Linden Tree Gifts in Noblesville (Indianapolis metro) run by Lauren Price: lessons, open play, leagues and events. Its own page says: "We play American mahjong using the current National Mah Jongg League (NMJL) card."', "website" = 'https://luckytilesmahjong.com/', "sourceUrl" = 'https://luckytilesmahjong.com/' WHERE "slug" = 'indianapolis-lucky-tiles-mahjong-the-atelier' AND "status" = 'NEEDS_REVIEW';
UPDATE "Club" SET "status" = 'INACTIVE', "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" IN ('richmond-hidden-tile-mahjong-club', 'san-diego-san-diego-mahjong-club-ding-tea-mira-mesa', 'san-diego-san-diego-mahjong-club-denny-s-miramar', 'san-diego-vinya-vino-vinyasa-san-diego-mahjong-club', 'seattle-seattle-mahjong-club-group') AND "status" = 'NEEDS_REVIEW';
